On 7/1/26 10:55, Lizhi Hou wrote:
> When a debug BO command completes, job->drv_cmd may already have been
> freed. Accessing it from aie2_sched_drvcmd_resp_handler() can result in
> a use-after-free and memory corruption.
> 
> Fix this by introducing reference counting for drv_cmd objects and
> transferring ownership to the job while it is in flight. This ensures
> that the command remains valid until the completion handler finishes
> processing it.
> 
> Fixes: 7ea046838021 ("accel/amdxdna: Support firmware debug buffer")
> Signed-off-by: Lizhi Hou <lizhi.hou@amd.com>
Reviwed-by: Mario Limonciello (AMD) <superm1@kernel.org>
> ---
>   drivers/accel/amdxdna/aie2_ctx.c    | 68 +++++++++++++++++++++--------
>   drivers/accel/amdxdna/amdxdna_ctx.h |  1 +
>   2 files changed, 51 insertions(+), 18 deletions(-)
> 
> diff --git a/drivers/accel/amdxdna/aie2_ctx.c b/drivers/accel/amdxdna/aie2_ctx.c
> index 55eb29dece5b..8ec8a4d69b14 100644
> --- a/drivers/accel/amdxdna/aie2_ctx.c
> +++ b/drivers/accel/amdxdna/aie2_ctx.c
> @@ -59,6 +59,18 @@ static bool aie2_tdr_detect(struct amdxdna_dev *xdna)
>   	return false;
>   }
>   
> +static void aie2_cmd_release(struct kref *ref)
> +{
> +	struct amdxdna_drv_cmd *drv_cmd = container_of(ref, struct amdxdna_drv_cmd, refcnt);
> +
> +	kfree(drv_cmd);
> +}
> +
> +static void aie2_cmd_put(struct amdxdna_drv_cmd *drv_cmd)
> +{
> +	kref_put(&drv_cmd->refcnt, aie2_cmd_release);
> +}
> +
>   static void aie2_job_release(struct kref *ref)
>   {
>   	struct amdxdna_sched_job *job;
> @@ -70,6 +82,8 @@ static void aie2_job_release(struct kref *ref)
>   	wake_up(&job->hwctx->priv->job_free_wq);
>   	if (job->out_fence)
>   		dma_fence_put(job->out_fence);
> +	if (job->drv_cmd)
> +		aie2_cmd_put(job->drv_cmd);
>   	kfree(job->aie2_job_health);
>   	kfree(job);
>   }
> @@ -901,7 +915,7 @@ static int aie2_hwctx_cfg_debug_bo(struct amdxdna_hwctx *hwctx, u32 bo_hdl,
>   {
>   	struct amdxdna_client *client = hwctx->client;
>   	struct amdxdna_dev *xdna = client->xdna;
> -	struct amdxdna_drv_cmd cmd = { 0 };
> +	struct amdxdna_drv_cmd *cmd;
>   	struct amdxdna_gem_obj *abo;
>   	u64 seq;
>   	int ret;
> @@ -912,32 +926,39 @@ static int aie2_hwctx_cfg_debug_bo(struct amdxdna_hwctx *hwctx, u32 bo_hdl,
>   		return -EINVAL;
>   	}
>   
> +	cmd = kzalloc_obj(*cmd);
> +	if (!cmd) {
> +		ret = -ENOMEM;
> +		goto put_obj;
> +	}
> +	kref_init(&cmd->refcnt);
> +
>   	if (attach) {
>   		if (abo->assigned_hwctx != AMDXDNA_INVALID_CTX_HANDLE) {
>   			ret = -EBUSY;
> -			goto put_obj;
> +			goto put_cmd;
>   		}
> -		cmd.opcode = ATTACH_DEBUG_BO;
> +		cmd->opcode = ATTACH_DEBUG_BO;
>   	} else {
>   		if (abo->assigned_hwctx != hwctx->id) {
>   			ret = -EINVAL;
> -			goto put_obj;
> +			goto put_cmd;
>   		}
> -		cmd.opcode = DETACH_DEBUG_BO;
> +		cmd->opcode = DETACH_DEBUG_BO;
>   	}
>   
> -	ret = amdxdna_cmd_submit(client, &cmd, AMDXDNA_INVALID_BO_HANDLE,
> +	ret = amdxdna_cmd_submit(client, cmd, AMDXDNA_INVALID_BO_HANDLE,
>   				 &bo_hdl, 1, hwctx->id, &seq);
>   	if (ret) {
>   		XDNA_ERR(xdna, "Submit command failed");
> -		goto put_obj;
> +		goto put_cmd;
>   	}
>   
>   	aie2_cmd_wait(hwctx, seq);
> -	if (cmd.result) {
> -		XDNA_ERR(xdna, "Response failure 0x%x", cmd.result);
> +	if (cmd->result) {
> +		XDNA_ERR(xdna, "Response failure 0x%x", cmd->result);
>   		ret = -EINVAL;
> -		goto put_obj;
> +		goto put_cmd;
>   	}
>   
>   	if (attach)
> @@ -947,6 +968,8 @@ static int aie2_hwctx_cfg_debug_bo(struct amdxdna_hwctx *hwctx, u32 bo_hdl,
>   
>   	XDNA_DBG(xdna, "Config debug BO %d to %s", bo_hdl, hwctx->name);
>   
> +put_cmd:
> +	aie2_cmd_put(cmd);
>   put_obj:
>   	amdxdna_gem_put_obj(abo);
>   	return ret;
> @@ -974,25 +997,32 @@ int aie2_hwctx_sync_debug_bo(struct amdxdna_hwctx *hwctx, u32 debug_bo_hdl)
>   {
>   	struct amdxdna_client *client = hwctx->client;
>   	struct amdxdna_dev *xdna = client->xdna;
> -	struct amdxdna_drv_cmd cmd = { 0 };
> +	struct amdxdna_drv_cmd *cmd;
>   	u64 seq;
>   	int ret;
>   
> -	cmd.opcode = SYNC_DEBUG_BO;
> -	ret = amdxdna_cmd_submit(client, &cmd, AMDXDNA_INVALID_BO_HANDLE,
> +	cmd = kzalloc_obj(*cmd);
> +	if (!cmd)
> +		return -ENOMEM;
> +	kref_init(&cmd->refcnt);
> +
> +	cmd->opcode = SYNC_DEBUG_BO;
> +	ret = amdxdna_cmd_submit(client, cmd, AMDXDNA_INVALID_BO_HANDLE,
>   				 &debug_bo_hdl, 1, hwctx->id, &seq);
>   	if (ret) {
>   		XDNA_ERR(xdna, "Submit command failed");
> -		return ret;
> +		goto put_cmd;
>   	}
>   
>   	aie2_cmd_wait(hwctx, seq);
> -	if (cmd.result) {
> -		XDNA_ERR(xdna, "Response failure 0x%x", cmd.result);
> -		return -EINVAL;
> +	if (cmd->result) {
> +		XDNA_ERR(xdna, "Response failure 0x%x", cmd->result);
> +		ret = -EINVAL;
>   	}
>   
> -	return 0;
> +put_cmd:
> +	aie2_cmd_put(cmd);
> +	return ret;
>   }
>   
>   static int aie2_populate_range(struct amdxdna_gem_obj *abo)
> @@ -1139,6 +1169,8 @@ int aie2_cmd_submit(struct amdxdna_hwctx *hwctx, struct amdxdna_sched_job *job,
>   		dma_resv_add_fence(job->bos[i]->resv, job->out_fence, DMA_RESV_USAGE_WRITE);
>   	job->seq = hwctx->priv->seq++;
>   	kref_get(&job->refcnt);
> +	if (job->drv_cmd)
> +		kref_get(&job->drv_cmd->refcnt);
>   	drm_sched_entity_push_job(&job->base);
>   
>   	*seq = job->seq;
> diff --git a/drivers/accel/amdxdna/amdxdna_ctx.h b/drivers/accel/amdxdna/amdxdna_ctx.h
> index aaae16430466..b6bef3af7dab 100644
> --- a/drivers/accel/amdxdna/amdxdna_ctx.h
> +++ b/drivers/accel/amdxdna/amdxdna_ctx.h
> @@ -132,6 +132,7 @@ enum amdxdna_job_opcode {
>   struct amdxdna_drv_cmd {
>   	enum amdxdna_job_opcode	opcode;
>   	u32			result;
> +	struct kref		refcnt;
>   };
>   
>   struct app_health_report;

On Thu, 25 Jun 2026 19:06:38 +0800
Chi-Wen Weng <cwweng.linux@gmail.com> wrote:

> From: Chi-Wen Weng <cwweng@nuvoton.com>
> 
> Add an IIO driver for the Nuvoton MA35D1 Enhanced ADC controller.
> 
> The driver supports direct raw reads and triggered buffered capture. The
> controller end-of-conversion interrupt is exposed as the device trigger
> and is used to push samples into the IIO buffer.
> 
> Channels are described by firmware child nodes and can be configured as
> single-ended or differential inputs. Since the differential enable bit is
> global, mixed single-ended and differential buffered scans are rejected.
> 
> DMA support is intentionally not included in this initial upstream driver;
> conversions are handled through the interrupt-driven path.
> 
> Signed-off-by: Chi-Wen Weng <cwweng@nuvoton.com>

A few minor additional comments in line. I've tried to avoid
duplication but there may be some there!

Jonathan
> diff --git a/drivers/iio/adc/ma35d1_eadc.c b/drivers/iio/adc/ma35d1_eadc.c
> new file mode 100644
> index 000000000000..0c075126e139
> --- /dev/null
> +++ b/drivers/iio/adc/ma35d1_eadc.c

...

> +}
> +
> +static int ma35d1_adc_read_raw(struct iio_dev *indio_dev,
> +			       const struct iio_chan_spec *chan,
> +			       int *val, int *val2, long mask)
> +{
> +	struct ma35d1_adc *adc = iio_priv(indio_dev);
> +	int ret;
> +
> +	switch (mask) {
> +	case IIO_CHAN_INFO_RAW:
> +		if (!iio_device_claim_direct(indio_dev))
> +			return -EBUSY;
> +
> +		mutex_lock(&adc->lock);

Look at the ACQUIRE() macros for claim direct stuff (in iio.h)
and then use guard() for this.  Be careful to add {} to define scope
to being this case block.  May not save much code but it will be easeir
to read than this currently is.

> +		ret = ma35d1_adc_read_conversion(indio_dev, chan, val);
> +		mutex_unlock(&adc->lock);
> +
> +		iio_device_release_direct(indio_dev);
> +		if (ret)
> +			return ret;
> +
> +		return IIO_VAL_INT;
> +	default:
> +		return -EINVAL;
> +	}
> +}

> +static int ma35d1_adc_parse_channels(struct iio_dev *indio_dev,
> +				     struct device *dev)
> +{
> +	struct ma35d1_adc *adc = iio_priv(indio_dev);
> +	DECLARE_BITMAP(used_channels, MA35D1_EADC_MAX_CHANNELS);
> +	struct fwnode_handle *child;
> +	struct iio_chan_spec *channels;
> +	int num_channels;
> +	int scan_index = 0;

Move assignment down to just above the loop.  Makes it easier for
reviewers to associate the initial value with what is going on.

> +	int ret;
> +
> +	bitmap_zero(used_channels, MA35D1_EADC_MAX_CHANNELS);
> +
> +	num_channels = device_get_child_node_count(dev);
> +	if (!num_channels)
> +		return dev_err_probe(dev, -ENODATA,
> +				     "no ADC channels configured\n");
> +
> +	if (num_channels > MA35D1_EADC_MAX_CHANNELS)
> +		return dev_err_probe(dev, -EINVAL, "too many ADC channels\n");
> +
> +	channels = devm_kcalloc(dev, num_channels + 1, sizeof(*channels),
> +				GFP_KERNEL);
> +	if (!channels)
> +		return -ENOMEM;
> +
> +	device_for_each_child_node(dev, child) {
...

> +
> +static int ma35d1_adc_probe(struct platform_device *pdev)
> +{
> +	struct device *dev = &pdev->dev;
> +	struct iio_dev *indio_dev;
> +	struct ma35d1_adc *adc;
> +	int irq;
> +	int ret;
> +
> +	indio_dev = devm_iio_device_alloc(dev, sizeof(*adc));
> +	if (!indio_dev)
> +		return -ENOMEM;
> +	adc = iio_priv(indio_dev);
> +	adc->dev = dev;
> +	mutex_init(&adc->lock);
For new code
	ret = devm_mutex_init(&adc->lock);
	if (ret)
		return ret;

The advantage this brings to debug is small but it's also very simple
so we are no doing it for all new code in IIO.

> +	init_completion(&adc->completion);
> +
> +	adc->regs = devm_platform_ioremap_resource(pdev, 0);
> +	if (IS_ERR(adc->regs))
> +		return dev_err_probe(dev, PTR_ERR(adc->regs),
> +				     "failed to map registers\n");
> +
> +	adc->clk = devm_clk_get_enabled(dev, NULL);
> +	if (IS_ERR(adc->clk))
> +		return dev_err_probe(dev, PTR_ERR(adc->clk),
> +				     "failed to get and enable ADC clock\n");
> +
> +	indio_dev->name = "ma35d1-eadc";
> +	indio_dev->modes = INDIO_DIRECT_MODE | INDIO_BUFFER_TRIGGERED;

Second part of this is set by the triggered_buffer call later. So don't set it
here.

> +	indio_dev->info = &ma35d1_adc_info;
> +
> +	ret = ma35d1_adc_parse_channels(indio_dev, dev);
> +	if (ret)
> +		return ret;
> +
> +	ma35d1_adc_hw_init(adc);
> +
> +	ret = devm_add_action_or_reset(dev, ma35d1_adc_hw_disable, adc);
> +	if (ret)
