+int erdt_get_max_rmid(int cpu)
+{
+	struct erdt_domain_info *d;
+	struct list_head *pos;
+
+	if (!__erdt_enabled)
+		return 0;
+
+	list_for_each(pos, &domain_info_list) {
+		d = container_of(pos, struct erdt_domain_info, list);
+
+		if (cpumask_test_cpu(cpu, d->cpu_mask))
